const KEY='reaction-room-v1';
let state={seen:[],examSeen:[],foundationSeen:[],foundationResults:[],arrowSeen:[],arrowResults:[],diagramSeen:[],diagramResults:[],drawSeen:[],drawResults:[],activeExam:null,results:[],lessons:[],notes:{}};let storageOK=true;
try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){storageOK=false}
let view='home',lesson=0,filter='all',kind='all',current=null,answered=false,selected=null,session=null,exam=state.activeExam||null,coachTopic='hx',coachStep=0,hintLevel=0,foundationCurrent=null,foundationAnswered=false,foundationSelected=null,arrowCurrent=null,arrowSource=null,arrowDestination=null,arrowPhase='arrow',arrowFeedback='',arrowCharge=null,arrowErrors=0,diagramCurrent=null,diagramAnswered=false,diagramFeedback='',diagramDraft={};
if(exam&&Array.isArray(exam.ids)&&exam.ids[exam.index]){current=EXAM_BANK.find(q=>q.id===exam.ids[exam.index])||null;const prior=exam.answers?.find(a=>a.id===current?.id);answered=Boolean(prior);selected=prior?.selected??null}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){storageOK=false;toast('Progress could not be saved. Export a backup before closing.')}};
const remaining=(topic='all',type='all')=>BANK.filter(q=>!state.seen.includes(q.id)&&(topic==='all'||q.topic===topic)&&(type==='all'||q.type===type));
const examRemaining=()=>EXAM_BANK.filter(q=>!(state.examSeen||[]).includes(q.id));
const questionById=id=>BANK.find(q=>q.id===id)||EXAM_BANK.find(q=>q.id===id);
const stats=t=>{const r=state.results.filter(x=>!t||x.topic===t);return{n:r.length,correct:r.filter(x=>x.correct).length,pct:r.length?Math.round(r.filter(x=>x.correct).length/r.length*100):0}};
const topicName=id=>MODULES.find(m=>m.id===id)?.title||id;
function toast(s){let e=document.createElement('div');e.className='toast';e.textContent=s;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function go(v){view=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function nav(){return [['home','⌂','Study desk'],['teach','◉','Teach me'],['foundation','◎','Foundation Lab'],['arrow','↬','Arrow Lab'],['diagram','⌁','Diagram Lab'],['coach','↝','Mechanism Coach'],['learn','▤','Detailed lessons'],['practice','◇','Fresh practice'],['draw','⌬','Structure Lab'],['exam','◷','Exam rehearsal'],['review','↗','Your progress'],['reference','≡','Quick reference']].map(([v,i,n])=>`<button class="nav ${view===v?'active':''}" data-go="${v}"><span class="nav-symbol">${i}</span>${n}</button>`).join('')}
function render(){const s=stats();state.drawSeen=state.drawSeen||[];state.drawResults=state.drawResults||[];state.foundationSeen=state.foundationSeen||[];state.foundationResults=state.foundationResults||[];state.arrowSeen=state.arrowSeen||[];state.arrowResults=state.arrowResults||[];state.diagramSeen=state.diagramSeen||[];state.diagramResults=state.diagramResults||[];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div><div class="brand"><span class="logo">R</span>Reaction Room</div><div class="course-name">Organic Chemistry II<br>OU · CHEM 3153-002</div></div><nav>${nav()}</nav><div class="sidebar-bottom"><div class="eyebrow">Your exam</div><b>Wednesday, Sept. 23</b><div class="small muted">${COURSE.instructor}</div><div class="progress"><i style="width:${state.lessons.length/MODULES.length*100}%"></i></div><span>${state.lessons.length} / ${MODULES.length} lessons complete</span></div></aside><div><header class="topbar"><b>Exam 1 <span> / Fall 2026</span></b><span class="pill">${remaining().length} questions · ${DRAW_BANK.length-state.drawSeen.length} structures</span></header><main class="main">${!storageOK?'<div class="notice">Browser storage is unavailable. Keep this tab open and export a backup before leaving.</div>':''}${({home:home,teach:teach,foundation:foundationLab,arrow:arrowLab,diagram:diagramLab,coach:coach,learn:learn,practice:practice,draw:structureLab,exam:examView,review:review,reference:reference})[view]()}</main></div></div>`;bind();}
function heading(k,t,p=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1>${p?`<p class="muted" style="margin:0">${p}</p>`:''}</div></div>`}
function scope(){return `<div class="notice">${COURSE.scope}</div>`}
const FOUNDATION_RESCUE=[
  ['Line structures','Every unlabeled corner and line end is carbon. Add enough hidden H atoms to give neutral carbon four bonds. Double and triple bonds count as two and three.','You need this to read every reactant and draw every product.','How many carbons are in a six-membered unlabeled ring? Six.'],
  ['Orbitals and hybridization','An sp³ carbon has four σ bonds and tetrahedral geometry. An sp² carbon has three σ directions plus one unhybridized p orbital. A row of neighboring p orbitals permits conjugation.','This controls resonance, Diels–Alder geometry, π MOs and aromaticity.','What breaks conjugation? An sp³ atom with no p orbital in the path.'],
  ['Formal charge and octets','Count bonds and lone pairs. Neutral carbon usually has four bonds, neutral oxygen two, and neutral nitrogen three. A three-bond carbon with no lone pair is commonly C⁺.','Charge checking catches impossible resonance contributors and mechanisms.','Can carbon have five ordinary bonds? No; that exceeds its octet.'],
  ['Nucleophile and electrophile','A nucleophile supplies electrons from a lone pair, negative charge or π bond. An electrophile accepts them at an electron-poor atom.','Every curved arrow connects an electron source to an electron destination.','In H–Br addition, the alkene π bond is the nucleophile and H is the electrophilic site.'],
  ['Curved arrows','The tail must begin on electrons. The head shows where those electrons finish. If a bond breaks, a separate arrow shows where its pair goes. Full arrows move two electrons.','Exam mechanisms are electron bookkeeping, not memorized decorations.','When H–Br breaks, the bond pair moves to Br, producing Br⁻.'],
  ['Resonance','Keep atoms and σ bonds fixed; move only π electrons or lone pairs. Contributors are drawings of one delocalized species, not separate compounds in equilibrium.','This generates 1,2, 1,4 and 1,6 capture sites and stabilizes arenium ions.','If an atom moved, you drew an isomer or reaction—not resonance.'],
  ['Stereochemistry','Wedge points toward you, dash points away. Syn means two groups add to one face; cis/trans compares sides; E/Z compares priority groups across C=C.','This is required for OsO₄ products and substituted Diels–Alder products.','Two stereocenters can still form an achiral meso compound when internal symmetry is present.'],
  ['Carbon accounting','Number or color every carbon before reacting. A reagent may join fragments, preserve a skeleton or cleave it; no carbon may silently appear or vanish.','This is the fastest error check for ozonolysis, Wittig, Diels–Alder and synthesis.','Wittig adds the ylide carbon to the carbonyl fragment; OsO₄ adds no carbon.']
];
const HINT_LADDERS={
  basics:['Translate every line end and corner into a carbon before reasoning.','Check ordinary valence: C=4, O=2, N=3; then add hidden H atoms.','Find the electron source first: a lone pair, negative charge or π bond.'],
  conjugation:['Number the original chain and locate every uninterrupted p-orbital position.','After terminal protonation, draw the cation and move one neighboring π pair at a time.','Attack every carbon that bears positive charge in a valid resonance contributor.'],
  energy:['Ask two separate questions: which barrier is smaller, and which product lies lower?','Measure each activation barrier from the valley immediately before its peak.','Lower barrier means kinetic; lower final free energy means thermodynamic.'],
  orbitals:['N interacting p orbitals make N π molecular orbitals.','Fill two electrons per orbital from lowest energy upward.','HOMO is the highest filled level; LUMO is the first empty level.'],
  diels:['Label the four diene atoms and two dienophile atoms before forming bonds.','Join both diene ends to the dienophile and move the remaining π bond between the inner diene atoms.','Preserve substituent cis/trans relationships and confirm the diene can reach s-cis.'],
  diol:['Do not cut the carbon skeleton. Convert C=C to C–C.','Place OH on both former alkene carbons.','Both C–O bonds must be on the same face because OsO₄ addition is syn.'],
  ozone:['Draw a vertical cut through every C=C.','Turn each original alkene carbon into a carbonyl carbon while retaining its substituents.','An alkene carbon with H gives an aldehyde; one with two carbon groups gives a ketone.'],
  wittig:['Mark the carbonyl carbon and ylide carbon.','Remove carbonyl O and phosphorus from the two reacting carbons.','Join those two carbons with C=C and retain all their other substituents.'],
  synthesis:['Identify the most distinctive target feature before choosing reagents.','Work backward one bond change: diol→alkene, cyclohexene→diene+dienophile, alkene→carbonyl+ylide.','Map every carbon, then verify the proposed route forward.'],
  aromatic:['Check cyclic, planar and continuously conjugated before counting electrons.','Count only electrons occupying the ring’s p-orbital circuit.','A qualifying 4n+2 system is aromatic; a qualifying 4n system is antiaromatic.'],
  eas:['The aromatic ring first attacks an activated electrophile.','Draw the σ complex with the electrophile and H on the same temporarily sp³ carbon.','A base removes that H; the C–H pair restores the missing π bond and aromaticity.']
};
const COACHES={
  hx:{title:'HBr addition to a conjugated diene or triene',lesson:'conjugation',steps:[
    ['Inventory and number','Number the conjugated chain before moving electrons. Mark the π bond that will take H.','Original numbering is how 1,2, 1,4 and 1,6 products are named.','Do all conjugated atoms have adjacent p orbitals?'],
    ['Protonate correctly','Push the chosen π pair to H. At the same time, push the H–Br bond pair onto Br.','The first arrow creates C–H; the second prevents an impossible overbonded H.','Did you produce Br⁻ and one carbocation?'],
    ['Expand resonance','Move the neighboring π pair toward the carbocation. Continue across a triene until every valid contributor is drawn.','Resonance reveals every electrophilic carbon that the bromide can capture.','Atoms and σ bonds must stay fixed.'],
    ['Capture each site','From a Br⁻ lone pair, draw an arrow to each cation site in a separate pathway.','Each valid resonance contributor can lead to a different constitutional product.','Does each product have neutral Br and four bonds at carbon?'],
    ['Label and compare','Label products by the original positions of H and Br, then compare barrier height separately from product stability.','Regiochemical name does not itself determine kinetic or thermodynamic control.','Did you locate every remaining C=C?']
  ]},
  diels:{title:'Diels–Alder ring construction',lesson:'diels',steps:[
    ['Prepare the partners','Put the diene in s-cis and label its atoms C1–C4. Label the dienophile C5–C6.','The diene ends must be close enough to make two bonds.','A diene locked s-trans cannot react by the normal pathway.'],
    ['Draw the cyclic arrows','Move three π pairs around one closed loop: make C1–C6, make C4–C5 and shift the inner diene π bond to C2=C3.','The reaction is concerted, so no free carbocation is inserted.','Are there exactly three arrows and two new σ bonds?'],
    ['Build the product','Draw ring order C1–C2=C3–C4–C5–C6 and transfer every substituent to its original atom.','This preserves atom count and prevents misplaced double bonds.','Is the remaining diene-derived C=C between the inner atoms?'],
    ['Audit stereochemistry','Preserve cis/trans relationships on the dienophile and evaluate endo/exo where a bridged product permits it.','Diels–Alder is stereospecific; substituent relationships do not randomize.','Did you include the mirror image if an achiral environment makes a racemic pair?']
  ]},
  diol:{title:'OsO₄/NMO syn dihydroxylation',lesson:'diol',steps:[
    ['Mark the alkene','Identify the two alkene carbons and everything attached to each.','Those same two carbons receive OH; no C–C σ bond is cut.','Will either carbon become a stereocenter?'],
    ['Add from one face','Replace C=C with C–C and make both C–O bonds from the same face.','The cyclic osmate ester delivers both oxygens syn.','Use two wedges or two dashes, not one of each.'],
    ['Release the diol','Hydrolysis converts the cyclic osmate ester into two neighboring OH groups; NMO regenerates active osmium.','NMO is a co-oxidant, not a carbon source or stereochemical director.','Are the OH groups vicinal and syn?'],
    ['Count stereoisomers','Check symmetry and existing stereocenters before deciding meso, racemic or diastereomeric.','Syn alone does not automatically mean meso.','For symmetric cis-2-butene, the syn product is meso.']
  ]},
  ozone:{title:'Reductive ozonolysis',lesson:'ozone',steps:[
    ['Mark every C=C','Circle both atoms of each alkene that ozone will cleave.','Each marked carbon becomes one carbonyl carbon.','For a ring, remember that cutting one π bond can open one molecule rather than make two.'],
    ['Cut and cap','Erase the C=C connection and draw C=O at both original alkene carbons.','This mechanical operation preserves all non-alkene substituents.','Did you cleave every alkene exactly once?'],
    ['Name the carbonyls','An original alkene C–H gives an aldehyde; an alkene carbon with two carbon substituents gives a ketone; =CH₂ gives formaldehyde.','Reductive DMS workup stops aldehydes from further oxidation.','Account for every starting carbon across all products.'],
    ['Run backward when needed','Remove carbonyl oxygens and reconnect the two carbonyl carbons with C=C.','Reverse mapping reconstructs an alkene, though original E/Z information is usually lost.','Does each reconnected carbon retain all former substituents?']
  ]},
  wittig:{title:'Wittig alkene formation',lesson:'wittig',steps:[
    ['Choose the two carbons','Mark the carbonyl carbon and the carbon directly bonded to PPh₃ in the ylide.','These become the two carbons of the new C=C.','No phenyl group from phosphorus transfers to the product.'],
    ['Attack the carbonyl','The nucleophilic ylide carbon attacks carbonyl carbon while the C=O π pair moves to O.','This makes the new C–C bond and an O⁻/P⁺ arrangement.','Are charge and octets valid?'],
    ['Close the four-membered ring','O⁻ bonds to P⁺ to give the O–P–C–C oxaphosphetane.','This organizes the atoms that will fragment to alkene and phosphine oxide.','Can you trace all four atoms around the ring?'],
    ['Fragment','Break the appropriate C–O and C–P bonds while forming C=C and P=O.','A strong P=O bond helps drive the reaction.','Did carbonyl O end in Ph₃P=O?'],
    ['Check the product','Retain every substituent on both alkene carbons and assign E/Z only when each has two different groups.','Carbon mapping is more reliable than memorizing a product picture.','Did the ylide contribute exactly its carbon fragment?']
  ]},
  eas:{title:'Benzene bromination by EAS',lesson:'eas',steps:[
    ['Activate Br₂','FeBr₃ acts as a Lewis acid and polarizes Br₂ to create a much stronger electrophilic bromine species.','Benzene is stabilized and needs an activated electrophile.','Do not treat FeBr₃ as a radical initiator.'],
    ['Attack from the ring','A benzene π pair forms C–Br while the Br–Br bond breaks toward the Lewis-acid complex.','This is the bond-forming step and temporarily destroys aromaticity.','The attacked carbon now bears both H and Br.'],
    ['Draw the σ complex','Show the positive charge delocalized through the three valid arenium-ion resonance contributors.','Resonance stabilizes the intermediate but does not make it aromatic.','Keep atoms fixed while moving only π electrons.'],
    ['Restore aromaticity','FeBr₄⁻ removes H from the Br-bearing carbon; the C–H pair becomes the missing π bond.','Substitution is completed because aromaticity returns.','Remove H, not Br.'],
    ['Audit products','The products are bromobenzene and HBr, with FeBr₃ regenerated.','Catalyst regeneration and restored three-π-bond ring complete the cycle.','Do not leave a saturated, positively charged ring as the final product.']
  ]}
};
function coach(){const c=COACHES[coachTopic],s=c.steps[coachStep],li=MODULES.findIndex(m=>m.id===c.lesson);return heading('Mechanism Coach',c.title,'Reveal one decision at a time and explain it aloud before moving on.')+`<div class="coach-tabs">${Object.entries(COACHES).map(([id,x])=>`<button class="btn ${id===coachTopic?'primary':''}" data-coach="${id}">${x.title}</button>`).join('')}</div><div class="coach-shell"><section class="card coach-step"><div class="coach-progress"><span>Step ${coachStep+1} of ${c.steps.length}</span><div class="progress"><i style="width:${(coachStep+1)/c.steps.length*100}%"></i></div></div><span class="phase-num">${coachStep+1}</span><h2>${s[0]}</h2><div class="coach-action"><div class="eyebrow">What to draw</div><p>${s[1]}</p></div><div class="coach-why"><div class="eyebrow">Why it works</div><p>${s[2]}</p></div><div class="coach-check"><div class="eyebrow">Stop and check</div><p>${s[3]}</p></div><div class="actions">${coachStep<c.steps.length-1?'<button class="btn primary" id="coach-next">Reveal next step →</button>':`<button class="btn primary" data-start="${c.lesson}">Try unseen problems →</button>`}<button class="btn" id="coach-reset">Start mechanism over</button><button class="btn" data-lesson="${li}">Open full lesson</button></div></section><aside class="card"><h3>How to use this coach</h3><ol class="small"><li>Draw the current step on paper before reading it.</li><li>Say where the arrow tail begins and where the pair ends.</li><li>Run the stop-check against your structure.</li><li>Only then reveal the next step.</li></ol><p class="note">This teaches the course-level mechanism sequence. On your exam, follow the drawing conventions used in lecture.</p></aside></div>`}
function reactionAtlas(){const data=[
  ['HX + conjugated diene/triene','Electrophilic addition','Adds H and X at 1,2 / 1,4 / 1,6 positions; carbon skeleton stays intact.','Regiochemistry depends on resonance capture; kinetic and thermodynamic comparisons are separate.','Reconnect X-bearing site to the delocalized carbocation logic.'],
  ['Diene + dienophile, heat','Diels–Alder [4+2]','Joins two fragments into one six-membered ring with two new C–C σ bonds.','Preserves dienophile cis/trans; evaluate endo/exo and enantiomers when relevant.','A cyclohexene often disconnects into a conjugated diene and alkene/alkyne.'],
  ['OsO₄, NMO; H₂O','Syn dihydroxylation','C=C becomes C–C and each alkene carbon gains OH; no carbon bond is cleaved.','Both C–O bonds form on one face; then test meso versus racemic.','Remove adjacent OH groups and restore C=C.'],
  ['1. O₃  2. DMS','Reductive ozonolysis','Cuts C=C; each alkene carbon becomes C=O. Rings open at the alkene.','E/Z information is usually destroyed. Aldehydes survive reductive workup.','Remove O from two carbonyl carbons and reconnect those carbons with C=C.'],
  ['Carbonyl + Ph₃P=CRR′','Wittig reaction','Replaces C=O with C=CRR′; the ylide carbon joins the carbonyl carbon.','Assign E/Z in the product; stabilized versus unstabilized ylide rules are tendencies.','Split a target C=C into a carbonyl partner and a ylide partner.'],
  ['Cyclic, planar, fully conjugated ring','Aromaticity test','No reaction is required: inspect the p-orbital circuit, then count π electrons.','4n+2 is aromatic and 4n is antiaromatic only after structural tests pass.','Check whether charge or a lone pair supplies a p orbital and two electrons.'],
  ['Benzene + Br₂/FeBr₃','Electrophilic aromatic substitution','Replaces one ring H with Br and restores the aromatic π system.','The σ complex is temporarily nonaromatic; final deprotonation restores aromaticity.','Product substituent replaces the original H on the attacked carbon.']
];return `<section class="card"><div class="section-title"><h2>Exam reaction atlas</h2><span class="tag">Forward and backward</span></div><div class="atlas">${data.map(([cue,name,change,stereo,reverse])=>`<details><summary><span>${name}</span><small>${cue}</small></summary><div class="atlas-grid"><p><b>Bond and carbon change</b>${change}</p><p><b>Selectivity check</b>${stereo}</p><p><b>Run it backward</b>${reverse}</p></div></details>`).join('')}</div></section>`}
function foundationRemaining(){return FOUNDATION_BANK.filter(q=>!state.foundationSeen.includes(q.id))}
function pickFoundation(){const pool=foundationRemaining();foundationCurrent=pool.length?pool[Math.floor(Math.random()*pool.length)]:null;foundationAnswered=false;foundationSelected=null;if(foundationCurrent){state.foundationSeen.push(foundationCurrent.id);save()}}
function foundationLab(){const results=state.foundationResults||[],correct=results.filter(r=>r.correct).length,skills=[...new Set(FOUNDATION_BANK.map(q=>q.skill))];if(!foundationCurrent){const rows=skills.map(skill=>{const qs=FOUNDATION_BANK.filter(q=>q.skill===skill),done=results.filter(r=>r.skill===skill),right=done.filter(r=>r.correct).length;return `<div class="foundation-skill"><b>${skill}</b><span>${done.length?right+'/'+done.length+' correct':'Not attempted'} · ${qs.filter(q=>!state.foundationSeen.includes(q.id)).length} fresh</span></div>`}).join('');return heading('Foundation Lab','Rebuild the exact O-Chem I skills this exam uses.',`${FOUNDATION_BANK.length} automatically scored micro-drills. Each prompt appears once.`)+`<div class="foundation-lab-grid"><section class="card"><div class="section-title"><h2>Your prerequisite evidence</h2><span class="tag">${correct}/${results.length||0} correct</span></div>${rows}</section><aside class="card"><h2>${foundationRemaining().length?'Ready for a five-minute rescue set?':'Foundation bank complete'}</h2><p class="muted">Short questions isolate one older skill at a time, explain the result immediately and preserve the no-repeat rule.</p><button class="btn primary" id="foundation-start" ${!foundationRemaining().length?'disabled':''}>${foundationRemaining().length?'Show a fresh micro-drill →':'All 24 drills completed'}</button><p class="note" style="margin-top:15px">A wrong answer is useful evidence. Review its explanation, then continue; later exam questions test the same skill in context.</p></aside></div>`}const q=foundationCurrent;return heading('Foundation Lab',q.skill,`${foundationRemaining().length} unseen prerequisite drills remain.`)+`<div class="question"><div class="card"><div class="qhead"><span class="eyebrow">Prerequisite rescue</span><span class="tag">Automatically scored</span></div><div class="qprompt">${q.prompt}</div><div class="choices">${q.choices.map((c,i)=>`<button class="choice ${foundationAnswered?(i===q.answer?'correct':i===foundationSelected?'wrong':''):''}" data-foundation-choice="${i}" ${foundationAnswered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${c}</span></button>`).join('')}</div>${foundationAnswered?`<div class="feedback"><h3>${foundationSelected===q.answer?'Correct—keep the rule.':'Repair the rule before moving on.'}</h3><p>${q.explanation}</p></div>`:''}<div class="qfooter"><span class="note">${q.id}</span><button class="btn primary" id="foundation-next" ${!foundationAnswered?'disabled':''}>${foundationRemaining().length?'Next fresh drill →':'Finish Foundation Lab'}</button></div></div></div>`}
function arrowRemaining(){return ARROW_BANK.filter(q=>!state.arrowSeen.includes(q.id))}
function pickArrow(){const pool=arrowRemaining();arrowCurrent=pool.length?pool[Math.floor(Math.random()*pool.length)]:null;arrowSource=null;arrowDestination=null;arrowPhase='arrow';arrowFeedback='';arrowCharge=null;arrowErrors=0;if(arrowCurrent){state.arrowSeen.push(arrowCurrent.id);save()}}
function arrowLab(){const results=state.arrowResults||[],right=results.filter(r=>r.correct).length;if(!arrowCurrent)return heading('Arrow Lab','Move electrons, then audit the charge.','Twelve no-repeat checkpoints validate arrow origin, destination and formal-charge consequences.')+`<div class="arrow-overview"><section class="card"><h2>What this lab checks</h2><div class="readiness-grid"><div><h3>Arrow tail</h3><p>The selected source must actually contain the electron pair.</p></div><div><h3>Arrow head</h3><p>The destination must be the atom or bond that receives those electrons.</p></div><div><h3>Octet result</h3><p>Companion bond-breaking arrows prevent impossible valence.</p></div><div><h3>Formal charge</h3><p>Every completed movement ends with an explicit charge or bond-count audit.</p></div></div></section><aside class="card"><div class="eyebrow">Your evidence</div><h2>${right}/${results.length||0} correct first try</h2><p class="muted">${arrowRemaining().length} unseen arrow checkpoints remain.</p><button class="btn primary" id="arrow-start" ${!arrowRemaining().length?'disabled':''}>${arrowRemaining().length?'Start a fresh arrow check →':'Arrow bank complete'}</button></aside></div>`;const q=arrowCurrent,preview=arrowSource!==null&&arrowDestination!==null?`<div class="arrow-preview"><span>${q.sources[arrowSource]}</span><b>⟶</b><span>${q.destinations[arrowDestination]}</span></div>`:'';const sourceButtons=q.sources.map((x,i)=>`<button class="arrow-option ${arrowSource===i?'active':''}" data-arrow-source="${i}">${x}</button>`).join(''),destinationButtons=q.destinations.map((x,i)=>`<button class="arrow-option ${arrowDestination===i?'active':''}" data-arrow-destination="${i}">${x}</button>`).join('');let work='';if(arrowPhase==='arrow')work=`<div class="arrow-picker"><div><h3>1 · Arrow tail begins at</h3>${sourceButtons}</div><div><h3>2 · Arrow head ends at</h3>${destinationButtons}</div></div>${preview}${arrowFeedback?`<div class="draw-result wrong">${arrowFeedback}</div>`:''}<button class="btn primary" id="arrow-check" ${arrowSource===null||arrowDestination===null?'disabled':''}>Check electron movement</button>`;else{const chargeChoices=q.chargeChoices.map((x,i)=>`<button class="choice ${arrowPhase==='done'?(i===q.chargeAnswer?'correct':i===arrowCharge?'wrong':''):''}" data-arrow-charge="${i}" ${arrowPhase==='done'?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${x}</span></button>`).join('');work=`<div class="draw-result correct"><b>Electron movement accepted.</b><p>${q.why}</p></div><h3 style="margin-top:22px">Formal-charge audit</h3><div class="qprompt" style="font-size:19px">${q.chargePrompt}</div><div class="choices">${chargeChoices}</div>${arrowPhase==='done'?`<div class="feedback"><h3>${arrowCharge===q.chargeAnswer?'Charge audit correct.':'Charge audit needs repair.'}</h3><p>${q.chargeWhy}</p></div><button class="btn primary" id="arrow-next">${arrowRemaining().length?'Next fresh checkpoint →':'Finish Arrow Lab'}</button>`:''}`};return heading('Arrow Lab',q.title,`${arrowRemaining().length} unseen checkpoints remain · ${q.topic}`)+`<div class="card arrow-card"><div class="eyebrow">Structure state</div><div class="chem arrow-diagram">${q.diagram}</div><p>${q.instruction}</p>${work}</div>`}
function diagramRemaining(){return DIAGRAM_BANK.filter(q=>!state.diagramSeen.includes(q.id))}
function pickDiagram(){const pool=diagramRemaining();diagramCurrent=pool.length?pool[Math.floor(Math.random()*pool.length)]:null;diagramAnswered=false;diagramFeedback='';diagramDraft={};if(diagramCurrent){state.diagramSeen.push(diagramCurrent.id);save()}}
const numberField=(id,label)=>`<label class="diagram-field"><span>${label}</span><input id="${id}" type="number" inputmode="numeric" autocomplete="off" value="${diagramDraft[id]??''}" ${diagramAnswered?'disabled':''}></label>`;
function diagramLab(){
  const results=state.diagramResults||[],right=results.filter(r=>r.correct).length;
  if(!diagramCurrent)return heading('Diagram Lab','Build the diagram, then let the software score it.','Twelve no-repeat orbital and reaction-coordinate constructions use entered values, occupancies and classifications.')+`<div class="arrow-overview"><section class="card"><h2>Two visual skills your exam can demand</h2><div class="readiness-grid"><div><h3>π molecular orbitals</h3><p>Build all N levels from N p orbitals, fill the electron count and identify HOMO, LUMO and nodes.</p></div><div><h3>Reaction coordinates</h3><p>Measure each barrier from its own starting valley, then separate rate from final product stability.</p></div></div></section><aside class="card"><div class="eyebrow">Constructed evidence</div><h2>${right}/${results.length||0} diagrams correct</h2><p class="muted">${diagramRemaining().length} unseen builders remain.</p><button class="btn primary" id="diagram-start" ${!diagramRemaining().length?'disabled':''}>${diagramRemaining().length?'Build a fresh diagram →':'Diagram bank complete'}</button></aside></div>`;
  const q=diagramCurrent;
  let builder='';
  if(q.kind==='mo'){
    const levels=Array.from({length:q.levels},(_,i)=>{const n=q.levels-i,v=diagramDraft[`mo-${n}`];return `<div class="mo-level"><span>ψ${n}</span><i></i><select id="mo-${n}" aria-label="Electrons in psi ${n}" ${diagramAnswered?'disabled':''}><option value="">electrons?</option><option value="0" ${v==='0'?'selected':''}>0</option><option value="1" ${v==='1'?'selected':''}>1 ↑</option><option value="2" ${v==='2'?'selected':''}>2 ↑↓</option></select></div>`}).join('');
    builder=`<div class="diagram-build"><div class="mo-stack" aria-label="Molecular orbital energy levels"><b>higher energy</b>${levels}<b>lower energy</b></div><div class="diagram-inputs">${numberField('mo-homo','HOMO is ψ…')}${numberField('mo-lumo','LUMO is ψ…')}${numberField('mo-nodes','Nodes in HOMO')}</div></div>`;
  }else{
    const options=id=>['Path A','Path B','1,2 product','1,4 product'].map(x=>`<option ${diagramDraft[id]===x?'selected':''}>${x}</option>`).join('');
    builder=`<div class="energy-sketch" aria-label="Two-path reaction coordinate"><svg viewBox="0 0 620 210"><path d="M25 155 C90 155 105 45 175 45 S240 150 305 150"/><path d="M25 155 C100 155 130 18 215 18 S320 188 410 188"/><line x1="20" y1="190" x2="585" y2="190"/><text x="28" y="177">reactants</text><text x="285" y="140">A</text><text x="410" y="180">B</text></svg></div><div class="diagram-inputs four">${numberField('barrier-a','Path A ΔG‡')}${numberField('barrier-b','Path B ΔG‡')}${numberField('product-a','Product A ΔG')}${numberField('product-b','Product B ΔG')}<label class="diagram-field"><span>Forms faster</span><select id="fast" ${diagramAnswered?'disabled':''}><option value="">choose</option>${options('fast')}</select></label><label class="diagram-field"><span>More stable</span><select id="stable" ${diagramAnswered?'disabled':''}><option value="">choose</option>${options('stable')}</select></label></div>`;
  }
  return heading('Diagram Lab',q.title,`${diagramRemaining().length} unseen builders remain · ${q.kind==='mo'?'π orbital construction':'reaction-coordinate construction'}`)+`<div class="card diagram-card"><div class="qprompt">${q.prompt}</div>${builder}<div id="diagram-feedback">${diagramFeedback}</div><div class="qfooter"><span class="note">Enter numbers without units.</span>${diagramAnswered?`<button class="btn primary" id="diagram-next">${diagramRemaining().length?'Next fresh builder →':'Finish Diagram Lab'}</button>`:'<button class="btn primary" id="diagram-check">Score my diagram</button>'}</div></div>`;
}
function teach(){
  let next=MODULES.findIndex(m=>!state.lessons.includes(m.id));if(next<0)next=0;
  const phases=[
    ['1 · Learn the language','Read line structures, count hidden atoms, assign charge and move electron pairs.','basics'],
    ['2 · Control conjugated systems','Generate every resonance site, distinguish kinetic from thermodynamic control and read π MOs.','conjugation'],
    ['3 · Build and transform alkenes','Use Diels–Alder, syn dihydroxylation, ozonolysis and Wittig in both directions.','diels'],
    ['4 · Solve syntheses','Map every carbon, choose a strategic disconnection and verify each intermediate forward.','synthesis'],
    ['5 · Coverage check','Classify aromatic rings and draw introductory benzene bromination by EAS.','aromatic']
  ];
  const phaseCards=phases.map(([title,body,id])=>{const i=MODULES.findIndex(m=>m.id===id);return `<article class="teach-phase"><span class="phase-num">${title.split(' · ')[0]}</span><div><h3>${title.split(' · ')[1]}</h3><p>${body}</p><button class="btn text" data-lesson="${i}">Begin this stage →</button></div></article>`}).join('');
  const foundationCards=FOUNDATION_RESCUE.map(([title,plain,why,check],i)=>`<details class="foundation-card" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>${title}</summary><div><p>${plain}</p><p><b>Why it appears on this exam:</b> ${why}</p><div class="foundation-check"><b>Quick check</b><span>${check}</span></div></div></details>`).join('');
  const rows=[
    ['A π bond, lone pair or negative charge reacts','Find the electron source and electron-poor destination; every curved-arrow tail begins at electrons.'],
    ['HX meets a conjugated diene or triene','Protonate once, draw the full resonance family, then attack every cation site.'],
    ['A diene and dienophile make a six-membered ring','Use Diels–Alder; require s-cis, preserve cis/trans and leave the π bond between the inner diene atoms.'],
    ['OsO₄/NMO appears','Replace C=C with C–C bearing two syn OH groups; do not break the carbon skeleton.'],
    ['O₃ then DMS appears','Cut every C=C into two C=O groups; alkene C–H gives an aldehyde and alkene C–C gives a ketone.'],
    ['A carbonyl reacts with Ph₃P=CRR′','Replace C=O with C=CRR′; the carbonyl carbon and ylide carbon form the new alkene.'],
    ['A ring may be aromatic','Check cyclic, planar and fully conjugated first; only then count 4n+2 versus 4n π electrons.'],
    ['Br₂/FeBr₃ reacts with benzene','Form the electrophile, attack to the arenium ion, show resonance, then deprotonate to restore aromaticity.']
  ].map(([a,b])=>`<div class="decision-row"><b>${a}</b><span>${b}</span></div>`).join('');
  return heading('Teach me','Your complete Exam 1 course','Start at zero, rebuild the needed foundations, then prove each skill with unseen questions.')+scope()+`<section class="teach-hero"><div><span class="eyebrow">Guided course</span><h2>No textbook open beside you is required</h2><p>Every lesson defines the vocabulary, teaches a repeatable method, works an example, names common traps and ends with a mastery checklist. Reaction Room then sends you to topic practice that permanently retires each question after it appears.</p><div class="actions"><button class="btn primary" data-lesson="${next}">${state.lessons.length?'Continue at lesson '+(next+1):'Start from the beginning'} →</button><button class="btn" data-go="coach">Open Mechanism Coach</button><button class="btn" data-go="reference">Open reaction map</button></div></div><div class="teach-meter"><strong>${state.lessons.length}/${MODULES.length}</strong><span>lessons studied</span><div class="progress"><i style="width:${state.lessons.length/MODULES.length*100}%"></i></div><small>Completion records coverage. Practice accuracy is separate evidence.</small></div></section><section class="card"><div class="section-title"><div><div class="eyebrow">Organic Chemistry I restart</div><h2 style="margin-top:7px">Zero-knowledge bridge</h2></div><span class="tag">Only prerequisites used on Exam 1</span></div><p class="muted">Open every card you cannot explain from memory. These are the minimum older skills the reaction lessons rely on.</p><div class="foundation-grid">${foundationCards}</div></section><div class="teach-grid"><section class="card"><div class="section-title"><h2>The path from zero to exam-ready</h2><span class="tag">Use in order</span></div>${phaseCards}</section><aside class="card teach-routine"><div class="eyebrow">Use on every problem</div><h2>The five-pass method</h2><ol><li><b>Inventory:</b> identify functional groups, charges, stereochemistry and every carbon.</li><li><b>Classify:</b> name the reaction family before drawing a product.</li><li><b>Map:</b> mark the atoms and bonds that change; preserve everything else.</li><li><b>Execute:</b> draw electron flow, intermediates, products and required stereochemistry.</li><li><b>Audit:</b> check atoms, valence, charge, regiochemistry, stereochemistry and reagents.</li></ol><button class="btn primary" data-go="draw">Practice drawing structures →</button></aside></div><section class="card"><div class="section-title"><h2>Reaction chooser</h2><span class="tag">Recognition before memorization</span></div><div class="decision-table">${rows}</div></section><section class="card"><div class="section-title"><h2>What “ready” means</h2><span class="tag">Retrieval, not recognition</span></div><div class="readiness-grid"><div><h3>Mechanisms</h3><p>Draw arrows from electrons, include H–X cleavage, resonance contributors, cyclic intermediates where taught and aromaticity-restoring deprotonation.</p></div><div><h3>Structures</h3><p>Build products from skeletal reactants, preserve carbon count and show wedges, dashes, enantiomers or meso symmetry when required.</p></div><div><h3>Energy and orbitals</h3><p>Label axes, barriers, intermediates and product energies; fill π MOs and identify the relevant HOMO/LUMO pair.</p></div><div><h3>Synthesis</h3><p>Work backward one bond change at a time, then verify the complete sequence forward with every intermediate and reagent.</p></div></div><p class="note">This course is self-contained for the posted Exam 1 scope captured from Canvas. The instructor’s newest announcement or in-class scope change takes precedence.</p></section>`;
}
function home(){let s=stats(),next=MODULES.findIndex(m=>!state.lessons.includes(m.id));if(next<0)next=0;return heading('Your two-day study desk','Build understanding. Then test it.','A focused route from the fundamentals to exam-style reasoning.')+scope()+`<div class="grid"><section><div class="card feature"><div class="eyebrow">${state.lessons.length?'Continue your learning path':'Start here · no warm-up required'}</div><h2>${MODULES[next].title}</h2><p>${MODULES[next].intro}</p><button class="btn" data-lesson="${next}">${state.lessons.length?'Continue lesson':'Begin lesson 1'} <span>→</span></button><svg class="molecule" viewBox="0 0 200 200" aria-hidden="true"><path d="M100 15L174 57V143L100 185L26 143V57Z M100 32L159 66 M159 134L100 168 M41 134V66" fill="none" stroke="white" stroke-width="6"/></svg></div><div class="stats"><div class="stat"><strong>${state.lessons.length}/${MODULES.length}</strong><span>Lessons completed</span></div><div class="stat"><strong>${s.n?s.pct+'%':'—'}</strong><span>${s.n?'Practice accuracy':'No answers yet'}</span></div><div class="stat"><strong>${remaining().length}</strong><span>Fresh questions left</span></div></div><div class="card"><div class="section-title"><h2>Your learning path</h2><span class="tag">In prerequisite order</span></div>${MODULES.map((m,i)=>`<div class="module"><div class="module-num">${state.lessons.includes(m.id)?'✓':String(i+1).padStart(2,'0')}</div><div class="module-body"><h3>${m.title}</h3><p>${m.minutes} min · ${BANK.filter(q=>q.topic===m.id).length} questions · ${m.short}</p></div><button data-lesson="${i}" aria-label="Open ${m.title}">→</button></div>`).join('')}</div></section><aside><div class="card"><div class="eyebrow">Until Wednesday</div><h2 style="margin-top:12px">Your study sprint</h2>${COURSE.plan.map(([a,b])=>`<div class="step"><i class="dot"></i><div><b>${a}</b><p class="muted">${b}</p></div></div>`).join('')}<p class="note" style="margin-top:18px">Take a short break after each 40–50 minute block. Reconstruct answers from memory before checking them.</p></div><div class="card"><h3>Practice without repeats</h3><p class="small muted">${BANK.length} distinct prompts. Once a question is shown, it stays out of fresh practice—even after a reload. Concepts recur in different problems.</p><button class="btn primary" data-start="all">Start fresh practice →</button><p class="note" style="margin-top:15px">Saved in this browser only. Use Export progress to move your history. The bank stops when exhausted; it never silently recycles.</p></div></aside></div>`}
function learn(){const m=MODULES[lesson];return heading('Learn from scratch',m.title,m.intro)+`<div class="lesson-layout"><aside class="lesson-menu">${MODULES.map((x,i)=>`<button class="${i===lesson?'active':''}" data-lesson="${i}">${state.lessons.includes(x.id)?'✓':String(i+1).padStart(2,'0')} · ${x.title}</button>`).join('')}</aside><article class="card lesson"><span class="tag">${m.minutes} min · ${m.short}</span>${m.html}<h3>Before you move on</h3>${m.checks.map(x=>`<label class="checkrow"><input type="checkbox"><span>${x}</span></label>`).join('')}<div class="actions" style="margin-top:25px"><button class="btn primary" id="complete">${state.lessons.includes(m.id)?'Completed ✓':'Mark lesson complete'}</button><button class="btn" data-start="${m.id}">Practice this topic</button>${lesson<MODULES.length-1?`<button class="btn" data-lesson="${lesson+1}">Next lesson →</button>`:''}</div><p class="note" style="margin-top:18px">Completing a lesson records that you studied it. Practice results are tracked separately.</p></article></div>`}
function pick(){const pool=remaining(filter,kind);if(!pool.length){current=null;return}const ranked=pool.map(q=>{const s=stats(q.topic);return{q,score:Math.random()+(!s.n ? .4 : (1-s.pct/100)*.7)}}).sort((a,b)=>b.score-a.score);current=ranked[0].q;state.seen.push(current.id);save();answered=false;selected=null;hintLevel=0;}
function start(t='all'){filter=t;kind='all';session=null;exam=null;pick();go('practice')}
function practice(){return heading('Fresh practice','One problem. One clear explanation.','Think it through before revealing the answer.')+`<div class="controls"><label for="topic" class="small">Topic</label><select id="topic"><option value="all">All topics · focus on weaker areas</option>${MODULES.map(m=>`<option value="${m.id}" ${filter===m.id?'selected':''}>${m.title}</option>`).join('')}</select><label for="kind" class="small">Format</label><select id="kind"><option value="all">All formats</option><option value="mc" ${kind==='mc'?'selected':''}>Quick checks</option><option value="written" ${kind==='written'?'selected':''}>Written / drawing practice</option></select></div>`+(current?questionCard(false):`<div class="card empty"><h2>${remaining(filter,kind).length?'Ready for a fresh question?':'You’ve seen every question in this selection.'}</h2><p class="muted">${remaining(filter,kind).length?'Every shown question is saved to your history.':'Choose a different topic or review your explanations. Your history will not be reset automatically.'}</p>${remaining(filter,kind).length?'<button class="btn primary" id="next">Show a fresh question</button>':''}</div>`)}
function helpLadder(q){const hints=HINT_LADDERS[q.topic]||[];if(!hints.length||answered)return'';const shown=hints.slice(0,hintLevel).map((h,i)=>`<div class="hint-rung"><b>Hint ${i+1}</b><span>${h}</span></div>`).join('');const next=hintLevel<hints.length?`<button class="btn text" data-hint="${hintLevel+1}">${hintLevel?'Reveal a stronger hint':'I’m stuck—give me a hint'} →</button>`:'<span class="note">All coaching hints shown. Make your best attempt before checking.</span>';return `<div class="help-ladder"><div class="eyebrow">Help ladder</div><h3>Use only as much help as you need</h3>${shown}${next}</div>`}
function questionCard(isExam){const q=current;return `<div class="question"><div class="card"><div class="qhead"><span class="eyebrow">${topicName(q.topic)}</span><span class="tag">${q.type==='written'?'Written response · self-assessed':'Quick check · automatically scored'}${isExam?' · '+(exam.index+1)+' / '+exam.ids.length:''}</span></div><div class="qprompt">${q.prompt}</div>${q.visual||''}${q.type==='mc'?`<div class="choices">${q.choices.map((c,i)=>`<button class="choice ${answered&&!isExam?(i===q.answer?'correct':i===selected?'wrong':''):''}" data-choice="${i}" ${answered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(c)}</span></button>`).join('')}</div>`:`<label for="written" class="small muted">Write your reasoning here. For structures and curved arrows, draw on paper first.</label><textarea id="written" placeholder="My reasoning…" ${answered?'disabled':''}>${esc(state.notes[q.id]||'')}</textarea>${!answered?`<button class="btn primary" id="reveal" style="margin-top:15px">${isExam?'Save response':'Reveal answer & checklist'}</button>`:''}`}${answered&&!isExam?`<div class="feedback"><h3>${q.type==='mc'?(selected===q.answer?'That’s right.':'Let’s work through it.'):'Compare your work'}</h3><div>${q.explanation}</div>${q.type==='written'?`<h3 style="margin-top:18px">Award yourself credit only if:</h3><ul>${q.rubric.map(r=>`<li>${r}</li>`).join('')}</ul>${!state.results.some(r=>r.id===q.id)?'<div class="actions"><button class="btn primary" data-grade="yes">I met every criterion</button><button class="btn" data-grade="no">I need more practice</button></div>':'<p class="small">Self-assessment saved.</p>'}`:''}<button class="btn text" data-lesson="${MODULES.findIndex(m=>m.id===q.topic)}">Revisit the lesson →</button></div>`:''}${answered&&isExam?'<div class="banner" style="margin-top:20px">Response saved. Feedback appears when you finish.</div>':''}<div class="qfooter"><span class="note">${esc(q.id)} · ${remaining(filter,kind).length} unseen in selection</span>${!isExam?`<div class="actions">${!answered?'<button class="btn" id="skip">Skip & retire</button>':''}<button class="btn primary" id="next" ${!answered?'disabled':''}>Next fresh question →</button></div>`:`<button class="btn primary" id="examnext" ${!answered?'disabled':''}>${exam.index===exam.ids.length-1?'Finish rehearsal':'Next question →'}</button>`}</div></div></div>`}
function record(correct,mode='practice'){if(state.results.some(r=>r.id===current.id))return;state.results.push({id:current.id,topic:current.topic,correct,type:current.type,mode,at:Date.now(),selected,assisted:hintLevel>0,hints:hintLevel});save()}
const baseQuestionCard=questionCard;
questionCard=function(isExam){let html=baseQuestionCard(isExam);if(isExam)return html.replace(/exam-\d+ · \d+ unseen in selection/,current.id+' · dedicated rehearsal pool');if(answered||!current)return html;const marker=current.type==='mc'?'<div class="choices">':'<label for="written"';return html.replace(marker,helpLadder(current)+marker)};
function examView(){if(exam?.finished)return examReport();if(exam)return heading('Exam rehearsal','Work from memory.','Feedback is held until you finish. This is a custom rehearsal, not a prediction of your exam.')+questionCard(true);const formsLeft=EXAM_FORMS.filter(f=>f.every(id=>!(state.examSeen||[]).includes(id))).length;return heading('Exam rehearsal','Find out what you can do unaided.','Dedicated forms stay untouched by Fresh Practice and Structure Lab.')+`<div class="card" style="max-width:850px"><h2>20-question balanced rehearsal</h2><p>Each form includes conceptual checks plus written or drawing prompts across the posted core. Set aside about 45 minutes, use blank paper and give every question a genuine attempt.</p><div class="exam-pool"><strong>${formsLeft}</strong><span>complete unseen form${formsLeft===1?'':'s'} remaining</span><small>${examRemaining().length} dedicated rehearsal questions have not appeared.</small></div><p class="muted">Your 89 Fresh Practice questions are a separate pool. Using or retiring them cannot reduce this rehearsal.</p><button class="btn primary" id="beginexam" ${!formsLeft?'disabled':''}>${formsLeft?'Begin unseen form →':'All rehearsal forms completed'}</button><p class="note" style="margin-top:18px">This is a study benchmark, not a prediction of the instructor’s format or grading. A form is retired when it begins so exact questions never repeat.</p></div>`}
function beginExam(){state.examSeen=state.examSeen||[];const ids=EXAM_FORMS.find(f=>f.every(id=>!state.examSeen.includes(id)));if(!ids)return;state.examSeen.push(...ids);exam={ids:[...ids],index:0,answers:[],start:Date.now(),finished:false};state.activeExam=exam;save();examPick();render()}
function examPick(){current=EXAM_BANK.find(q=>q.id===exam.ids[exam.index]);const prior=exam.answers.find(a=>a.id===current?.id);answered=Boolean(prior);selected=prior?.selected??null;hintLevel=0;state.activeExam=exam;save()}
function examReport(){
  const auto=exam.answers.filter(r=>r.type==='mc');
  const correct=auto.filter(r=>r.correct).length;
  const cards=exam.answers.map(r=>{
    const q=questionById(r.id);
    const status=q.type==='written'?'Self-assess below':(r.correct?'Correct':'Needs work');
    const response=q.type==='written'
      ? `<p class="muted">Your response: ${esc(state.notes[q.id]||'No typed response; compare your paper drawing.')}</p>`
      : `<p>Your answer: ${esc(q.choices[r.selected])}</p>`;
    let rubric='';
    if(q.rubric){
      const criteria=`<ul>${q.rubric.map(x=>`<li>${x}</li>`).join('')}</ul>`;
      const grading=state.results.some(x=>x.id===q.id)
        ? '<span class="small">Self-assessment saved.</span>'
        : `<div class="actions"><button class="btn" data-examgrade="${q.id}|yes">Meets every criterion</button><button class="btn" data-examgrade="${q.id}|no">Needs practice</button></div>`;
      rubric=criteria+grading;
    }
    return `<article class="card"><span class="tag">${topicName(q.topic)} · ${status}</span><h3 style="margin-top:15px">${q.prompt}</h3>${response}<div class="feedback">${q.explanation}${rubric}</div></article>`;
  }).join('');
  const summary=`Elapsed: ${Math.round((Date.now()-exam.start)/60000)} minutes · ${correct}/${auto.length} quick checks correct · written responses need your assessment.`;
  return heading('Rehearsal complete','Turn your misses into your next study block.',summary)+`<div class="actions" style="margin-bottom:25px"><button class="btn primary" data-go="review">View topic progress</button><button class="btn" id="newexam">Set up another rehearsal</button></div>${cards}`;
}
function review(){
  const s=stats();
  const wrong=state.results.filter(x=>!x.correct).slice().reverse();
  const written=state.results.filter(x=>x.type==='written').length;
  const foundationMap={'Line structures':'basics','Hybridization':'orbitals','Formal charge':'basics','Nucleophile/electrophile':'basics','Curved arrows':'basics','Resonance':'conjugation','Stereochemistry':'diol','Carbon accounting':'synthesis'};
  const arrowMap={'HBr protonation':'conjugation','Allylic resonance':'conjugation','Nucleophile capture':'conjugation','Wittig addition':'wittig','Diels–Alder':'diels','EAS':'eas','Formal charge':'basics'};
  const evidenceFor=id=>[
    ...state.results.filter(x=>x.topic===id).map(x=>({...x,mode:x.type==='written'?'written':'practice'})),
    ...(state.foundationResults||[]).filter(x=>foundationMap[x.skill]===id).map(x=>({...x,mode:'foundation',assisted:false})),
    ...(state.arrowResults||[]).filter(x=>arrowMap[x.topic]===id).map(x=>({...x,mode:'arrow',assisted:false})),
    ...(state.diagramResults||[]).filter(x=>x.topic===id).map(x=>({...x,mode:'diagram',assisted:false})),
    ...(state.drawResults||[]).filter(x=>x.topic===id&&x.attempts>0).map(x=>({...x,mode:'structure',assisted:x.assisted||!x.firstTry}))
  ];
  const topicRows=MODULES.map(m=>{
    const attempts=evidenceFor(m.id),correct=attempts.filter(x=>x.correct).length,pct=attempts.length?Math.round(correct/attempts.length*100):0,unassisted=attempts.filter(x=>x.correct&&!x.assisted).length,modes=new Set(attempts.filter(x=>x.correct).map(x=>x.mode)),constructed=[...modes].some(x=>['written','structure','arrow','diagram'].includes(x)),lessonDone=state.lessons.includes(m.id);
    const independent=lessonDone&&attempts.length>=5&&pct>=80&&unassisted>=4&&modes.size>=2&&constructed;
    const level=!attempts.length&&!lessonDone?'Not started':!lessonDone?'Learn first':pct<75&&attempts.length>=3?'Relearn':independent?'Independent evidence':constructed?'Building':'Needs constructed work';
    const result=attempts.length?`${correct}/${attempts.length} correct · ${pct}%`:'No assessed answers yet';
    const next=!lessonDone?'complete lesson':attempts.length<5?'reach 5 assessed attempts':pct<80?'raise accuracy to 80%':unassisted<4?'get 4 correct without help':modes.size<2?'use a second question format':!constructed?'complete a drawing or written task':'maintain with delayed recall';
    return `<div class="module"><div class="module-body"><div class="topic-title"><h3>${m.title}</h3><span class="mastery ${independent?'ready':''}">${level}</span></div><div class="progress"><i style="width:${pct}%"></i></div><p>${result} · ${unassisted} unassisted correct · ${modes.size} format${modes.size===1?'':'s'} · Next: ${next}</p></div><button data-start="${m.id}">Practice</button></div>`;
  }).join('');
  const mistakes=wrong.length?wrong.map(r=>{
    const q=questionById(r.id);
    if(!q)return '';
    const lessonIndex=MODULES.findIndex(m=>m.id===q.topic);
    return `<details style="padding:15px 0;border-top:1px solid var(--line)"><summary style="cursor:pointer;line-height:1.5">${q.prompt}</summary><div class="feedback">${q.explanation}</div><button class="btn text" data-lesson="${lessonIndex}">Review lesson →</button></details>`;
  }).join(''):'<p class="muted">Your missed questions will appear here with their reasoning.</p>';
  const summary=`${s.n+(state.foundationResults||[]).length+(state.arrowResults||[]).length+(state.diagramResults||[]).length+(state.drawResults||[]).filter(x=>x.attempts).length} assessed attempts across every lab · ${written} self-assessed written responses`;
  return heading('Your progress','Study the gaps, not the score.',summary)+`<div class="actions" style="margin-bottom:22px"><button class="btn" id="export">Export progress</button><label class="btn" for="import">Import progress</label><input id="import" type="file" accept="application/json" class="hidden"></div><div class="grid"><section><div class="card"><h2>Topic evidence</h2><p class="note">Independent evidence requires the lesson, at least five assessed attempts, 80% accuracy, four correct without help, two formats, and one constructed response such as a structure, arrow, diagram or written explanation.</p>${topicRows}</div><div class="card"><h2>Mistake notebook</h2><p class="note">These are explanations from your completed attempts, not repeated practice questions.</p>${mistakes}</div></section><aside><div class="card"><h3>What to do next</h3><p class="muted small">Follow the exact “Next” requirement beside a topic. When you miss, explain the rule, close the feedback, and solve a different unseen prompt from memory.</p><h3>Keep your history</h3><p class="small muted">Progress is saved only in this browser and for this address. Export before switching devices or clearing browser data, then import the file in the new browser. Imports merge question history to preserve the no-repeat rule.</p></div></aside></div>`;
}
function reference(){return heading('Quick reference','The rules worth being able to explain.','Use this after an attempt, then close it and reconstruct the reasoning.')+scope()+reactionAtlas()+REFERENCE+`<div class="card"><h2>Scope & sources</h2><p>${COURSE.provenance}</p>${COURSE.sources.map(([n,u])=>`<a class="source" href="${u}" target="_blank" rel="noreferrer">${n} ↗</a>`).join('')}<p class="note">Lessons and questions are original study material. No actual exam questions or instructor answer keys are included. The course’s current announcements and review materials take precedence.</p></div>`}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=Number(b.dataset.lesson);go('learn')});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));if(view==='draw')bindStructureLab();if($('#complete'))$('#complete').onclick=()=>{const id=MODULES[lesson].id;if(!state.lessons.includes(id))state.lessons.push(id);save();render()};['topic','kind'].forEach(id=>{if($('#'+id))$('#'+id).onchange=e=>{if(id==='topic')filter=e.target.value;else kind=e.target.value;current=null;render()}});if($('#next'))$('#next').onclick=()=>{pick();render()};if($('#skip'))$('#skip').onclick=()=>{pick();render()};if($('#written'))$('#written').oninput=e=>{state.notes[current.id]=e.target.value;save()};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(answered)return;selected=Number(b.dataset.choice);answered=true;if(view==='exam'){const r={id:current.id,correct:selected===current.answer,type:'mc',selected};exam.answers.push(r);record(r.correct,'exam')}else record(selected===current.answer);render()});if($('#reveal'))$('#reveal').onclick=()=>{answered=true;if(view==='exam')exam.answers.push({id:current.id,type:'written'});render()};document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{record(b.dataset.grade==='yes');render()});if($('#beginexam'))$('#beginexam').onclick=beginExam;if($('#examnext'))$('#examnext').onclick=()=>{if(exam.index===exam.ids.length-1){exam.finished=true;current=null}else{exam.index++;examPick()}render();window.scrollTo(0,0)};if($('#newexam'))$('#newexam').onclick=()=>{exam=null;render()};document.querySelectorAll('[data-examgrade]').forEach(b=>b.onclick=()=>{const [id,grade]=b.dataset.examgrade.split('|');const q=BANK.find(q=>q.id===id);if(!state.results.some(r=>r.id===id))state.results.push({id,topic:q.topic,type:'written',correct:grade==='yes',mode:'exam',at:Date.now()});save();render()});if($('#export'))$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,...state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='reaction-room-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)};if($('#import'))$('#import').onchange=async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.seen)||!Array.isArray(x.results)||!Array.isArray(x.lessons))throw Error();const known=new Set(BANK.map(q=>q.id));state.seen=[...new Set([...state.seen,...x.seen.filter(id=>known.has(id))])];for(const r of x.results){const q=BANK.find(q=>q.id===r.id);if(q&&typeof r.correct==='boolean'&&!state.results.some(s=>s.id===r.id))state.results.push({...r,topic:q.topic,type:q.type})}state.lessons=[...new Set([...state.lessons,...x.lessons.filter(id=>MODULES.some(m=>m.id===id))])];for(const [id,n]of Object.entries(x.notes||{}))if(known.has(id)&&typeof n==='string')state.notes[id]=n;state.drawSeen=[...new Set([...(state.drawSeen||[]),...(x.drawSeen||[]).filter(id=>DRAW_BANK.some(q=>q.id===id))])];save();render();toast('Progress merged. Your seen questions remain excluded.')}catch(err){toast('That file is not a valid progress backup.')}};document.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>{hintLevel=Number(b.dataset.hint);render()});document.querySelectorAll('[data-coach]').forEach(b=>b.onclick=()=>{coachTopic=b.dataset.coach;coachStep=0;go('coach')});if($('#coach-next'))$('#coach-next').onclick=()=>{coachStep++;render()};if($('#coach-reset'))$('#coach-reset').onclick=()=>{coachStep=0;render()}}
const baseBindWithExamPool=bind;
bind=function(){baseBindWithExamPool();document.querySelectorAll('[data-examgrade]').forEach(b=>b.onclick=()=>{const [id,grade]=b.dataset.examgrade.split('|'),q=questionById(id);if(q&&!state.results.some(r=>r.id===id))state.results.push({id,topic:q.topic,type:'written',correct:grade==='yes',mode:'exam',at:Date.now(),assisted:false,hints:0});save();render()});if($('#import'))$('#import').onchange=async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.seen)||!Array.isArray(x.results)||!Array.isArray(x.lessons))throw Error();const practiceIds=new Set(BANK.map(q=>q.id)),examIds=new Set(EXAM_BANK.map(q=>q.id)),allIds=new Set([...practiceIds,...examIds]),mergeIds=(a,b,bank)=>[...new Set([...(a||[]),...(b||[]).filter(id=>bank.some(q=>q.id===id))])],mergeResults=(a,b,bank)=>{const out=[...(a||[])];for(const r of b||[])if(bank.some(q=>q.id===r.id)&&!out.some(x=>x.id===r.id))out.push(r);return out};state.seen=[...new Set([...state.seen,...x.seen.filter(id=>practiceIds.has(id))])];state.examSeen=[...new Set([...(state.examSeen||[]),...(x.examSeen||[]).filter(id=>examIds.has(id))])];for(const r of x.results){const q=questionById(r.id);if(q&&typeof r.correct==='boolean'&&!state.results.some(s=>s.id===r.id))state.results.push({...r,topic:q.topic,type:q.type})}state.lessons=[...new Set([...state.lessons,...x.lessons.filter(id=>MODULES.some(m=>m.id===id))])];for(const [id,n]of Object.entries(x.notes||{}))if(allIds.has(id)&&typeof n==='string')state.notes[id]=n;state.drawSeen=mergeIds(state.drawSeen,x.drawSeen,DRAW_BANK);state.drawResults=mergeResults(state.drawResults,x.drawResults,DRAW_BANK);state.foundationSeen=mergeIds(state.foundationSeen,x.foundationSeen,FOUNDATION_BANK);state.foundationResults=mergeResults(state.foundationResults,x.foundationResults,FOUNDATION_BANK);state.arrowSeen=mergeIds(state.arrowSeen,x.arrowSeen,ARROW_BANK);state.arrowResults=mergeResults(state.arrowResults,x.arrowResults,ARROW_BANK);state.diagramSeen=mergeIds(state.diagramSeen,x.diagramSeen,DIAGRAM_BANK);state.diagramResults=mergeResults(state.diagramResults,x.diagramResults,DIAGRAM_BANK);if(!state.activeExam&&x.activeExam&&Array.isArray(x.activeExam.ids)&&x.activeExam.ids.every(id=>examIds.has(id)))state.activeExam=x.activeExam;save();render();toast('Progress merged across practice, labs and rehearsal without reintroducing seen questions.')}catch(err){toast('That file is not a valid progress backup.')}}}
const baseBindFoundation=bind;
bind=function(){baseBindFoundation();if($('#foundation-start'))$('#foundation-start').onclick=()=>{pickFoundation();render()};document.querySelectorAll('[data-foundation-choice]').forEach(b=>b.onclick=()=>{if(foundationAnswered)return;foundationSelected=Number(b.dataset.foundationChoice);foundationAnswered=true;state.foundationResults.push({id:foundationCurrent.id,skill:foundationCurrent.skill,correct:foundationSelected===foundationCurrent.answer,at:Date.now()});save();render()});if($('#foundation-next'))$('#foundation-next').onclick=()=>{pickFoundation();render()}}
const baseBindArrow=bind;
bind=function(){baseBindArrow();if($('#arrow-start'))$('#arrow-start').onclick=()=>{pickArrow();render()};document.querySelectorAll('[data-arrow-source]').forEach(b=>b.onclick=()=>{arrowSource=Number(b.dataset.arrowSource);arrowFeedback='';render()});document.querySelectorAll('[data-arrow-destination]').forEach(b=>b.onclick=()=>{arrowDestination=Number(b.dataset.arrowDestination);arrowFeedback='';render()});if($('#arrow-check'))$('#arrow-check').onclick=()=>{if(arrowSource===arrowCurrent.source&&arrowDestination===arrowCurrent.destination){arrowPhase='charge';arrowFeedback=''}else{arrowErrors++;arrowFeedback=arrowSource!==arrowCurrent.source?'The tail is not on the electron pair that moves. Find a lone pair or bond that can supply electrons.':'The source is valid, but the head does not end where those electrons must go.'}render()};document.querySelectorAll('[data-arrow-charge]').forEach(b=>b.onclick=()=>{if(arrowPhase==='done')return;arrowCharge=Number(b.dataset.arrowCharge);if(arrowCharge!==arrowCurrent.chargeAnswer)arrowErrors++;arrowPhase='done';state.arrowResults.push({id:arrowCurrent.id,topic:arrowCurrent.topic,correct:arrowErrors===0,at:Date.now()});save();render()});if($('#arrow-next'))$('#arrow-next').onclick=()=>{pickArrow();render()}}
const baseBindDiagram=bind;
bind=function(){baseBindDiagram();if($('#diagram-start'))$('#diagram-start').onclick=()=>{pickDiagram();render()};if($('#diagram-check'))$('#diagram-check').onclick=()=>{const q=diagramCurrent;let ok=false,detail='';if(q.kind==='mo'){for(let i=1;i<=q.levels;i++)diagramDraft[`mo-${i}`]=$(`#mo-${i}`)?.value||'';for(const id of ['mo-homo','mo-lumo','mo-nodes'])diagramDraft[id]=$(`#${id}`)?.value||'';const occupancy=q.electrons.every((n,i)=>Number(diagramDraft[`mo-${i+1}`])===n),frontier=Number(diagramDraft['mo-homo'])===q.homo&&Number(diagramDraft['mo-lumo'])===q.lumo,nodes=Number(diagramDraft['mo-nodes'])===q.nodes;ok=occupancy&&frontier&&nodes;detail=!occupancy?'The occupancy is off. Fill from the lowest level upward with at most two electrons per level.':!frontier?'The electron filling is right; re-identify the highest occupied and first empty levels.':!nodes?'The frontier levels are right; ψn has n−1 nodes.':''}else{for(const id of ['barrier-a','barrier-b','product-a','product-b','fast','stable'])diagramDraft[id]=$(`#${id}`)?.value||'';const values=Number(diagramDraft['barrier-a'])===q.barriers[0]&&Number(diagramDraft['barrier-b'])===q.barriers[1]&&Number(diagramDraft['product-a'])===q.products[0]&&Number(diagramDraft['product-b'])===q.products[1],labels=diagramDraft.fast===q.fast&&diagramDraft.stable===q.stable;ok=values&&labels;detail=!values?'At least one energy is wrong. Measure each barrier upward from the immediately preceding valley, and each product energy from the stated reference.':'The energies are right. Lower barrier means faster; lower final energy means more stable.'}diagramAnswered=true;diagramFeedback=`<div class="draw-result ${ok?'correct':'wrong'}"><b>${ok?'Diagram accepted.':'Diagram needs repair.'}</b><p>${ok?q.explain:detail}</p>${!ok?`<p class="note">Correct construction: ${q.explain}</p>`:''}</div>`;state.diagramResults.push({id:q.id,topic:q.topic,kind:q.kind,correct:ok,at:Date.now()});save();render()};if($('#diagram-next'))$('#diagram-next').onclick=()=>{pickDiagram();render()}}
const baseBindExamRecovery=bind;
bind=function(){baseBindExamRecovery();if(view==='exam'&&exam&&!exam.finished){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(answered)return;selected=Number(b.dataset.choice);answered=true;const r={id:current.id,correct:selected===current.answer,type:'mc',selected};exam.answers.push(r);state.activeExam=exam;record(r.correct,'exam');save();render()});if($('#reveal'))$('#reveal').onclick=()=>{if(answered)return;answered=true;exam.answers.push({id:current.id,type:'written'});state.activeExam=exam;save();render()};if($('#examnext'))$('#examnext').onclick=()=>{if(exam.index===exam.ids.length-1){exam.finished=true;current=null;state.activeExam=exam;save()}else{exam.index++;examPick()}render();window.scrollTo(0,0)}}if($('#newexam'))$('#newexam').onclick=()=>{exam=null;state.activeExam=null;save();render()}}
